import { useEffect, useState } from "react";
import { adminControlApi } from "../api/adminControl.js";
import { managementApi } from "../api/management.js";
import { ConfirmDialog } from "../components/shared/ConfirmDialog.jsx";
import { EmptyState, ErrorPanel, LoadingPanel, RadioGroup, RadioOption, Tab, TabList } from "../components/ui/index.jsx";
import { useAsyncData } from "../hooks/useAsyncData.js";
import { hasOperationalCapability } from "../lib/authz.js";
import { buildActiveStudyJsonPrompt } from "../lib/activeStudyPrompt.js";
import { Icon } from "../lib/icons.jsx";
import { formatDateTime, formatNumber } from "../lib/i18n.js";
import "./admin-active-study.css";

const CONTENT_AREAS = [
  ["sheets", "Sheets", "content.view", "file"],
  ["questions", "Questions", "assessments.view", "file-question"],
  ["imports", "Import history", "assessments.view", "activity"]
];

const QUESTION_PRESETS = {
  quick: { label: "Quick Quiz", mcq: 10, true_false: 0, multiple_select: 0 },
  standard: { label: "Standard Sheet", mcq: 20, true_false: 10, multiple_select: 0 },
  exam: { label: "Exam Style", mcq: 30, true_false: 0, multiple_select: 0 },
  mixed: { label: "Mixed", mcq: 15, true_false: 10, multiple_select: 5 },
  custom: { label: "Custom", mcq: 10, true_false: 0, multiple_select: 0 }
};

function humanize(value) {
  return String(value || "Not available").replaceAll("_", " ").replace(/\b\w/g, (letter) => letter.toUpperCase());
}

function bytes(value) {
  const size = Number(value);
  if (!Number.isFinite(size)) return "—";
  if (size < 1024 * 1024) return `${Math.max(1, Math.round(size / 1024))} KB`;
  return `${(size / (1024 * 1024)).toFixed(1)} MB`;
}

function AdminNotice({ error = null, message = "" }) {
  if (!error && !message) return null;
  const importErrors = Array.isArray(error?.payload?.errors) ? error.payload.errors : [];
  return <div className={`form-alert ${error ? "error" : "success"}`} role={error ? "alert" : "status"}>
    {error?.message || message}
    {importErrors.slice(0, 8).map((item, index) => <small key={`${item.index}-${item.field}-${index}`}>Question {Number(item.index) + 1 || "batch"} · {item.field}: {item.message}</small>)}
  </div>;
}

function BreadcrumbButton({ onClick, children }) {
  return <button className="admin-content-crumb" type="button" onClick={onClick}><Icon name="chevron-left" size={16} />{children}</button>;
}

export default function AdminContentManagement({ operationsSession, initialArea = "sheets" }) {
  const visible = CONTENT_AREAS.filter(([, , capability]) => hasOperationalCapability(operationsSession, capability));
  const [area, setArea] = useState(initialArea);
  const active = visible.some(([key]) => key === area) ? area : visible[0]?.[0];
  useEffect(() => { setArea(initialArea); }, [initialArea]);
  return <section className="admin-content-shell">
    <header className="admin-content-header">
      <div><p>Library</p><h1>Content and questions</h1><span>Manage the published learning catalog.</span></div>
      <TabList label="Content management areas" variant="tint" value={active} onChange={setArea}>{visible.map(([key, label, , icon]) => <Tab key={key} value={key}><Icon name={icon} size={17} />{label}</Tab>)}</TabList>
    </header>
    {active === "sheets" && <SheetsArea canManage={hasOperationalCapability(operationsSession, "content.manage")} />}
    {active === "questions" && <QuestionsArea canManage={hasOperationalCapability(operationsSession, "assessments.manage")} />}
    {active === "imports" && <ImportHistory canManage={hasOperationalCapability(operationsSession, "assessments.manage")} />}
  </section>;
}

function SubjectBrowser({ selected, onSelect, purpose = "sheets" }) {
  const [query, setQuery] = useState(""); const [college, setCollege] = useState(""); const [specialty, setSpecialty] = useState(""); const [year, setYear] = useState("");
  const data = useAsyncData(() => adminControlApi.contentSubjects({ query }), [query]);
  if (data.loading) return <LoadingPanel />;
  if (data.error) return <ErrorPanel message={data.error} onRetry={data.reload} />;
  if (selected) return null;
  const subjects = data.data.results || [];
  const colleges = [...new Set(subjects.map((item) => item.college_title || "Unassigned"))];
  const specialties = [...new Set(subjects.filter((item) => !college || (item.college_title || "Unassigned") === college).map((item) => item.specialty_title || "Unassigned"))];
  const years = [...new Set(subjects.filter((item) => (!college || (item.college_title || "Unassigned") === college) && (!specialty || (item.specialty_title || "Unassigned") === specialty)).map((item) => item.academic_year_title || "Unassigned"))];
  const visibleSubjects = subjects.filter((item) => (!college || (item.college_title || "Unassigned") === college) && (!specialty || (item.specialty_title || "Unassigned") === specialty) && (!year || (item.academic_year_title || "Unassigned") === year));
  return <section className="admin-content-section">
    <div className="admin-content-toolbar"><div><h2>Sheets by study path</h2><p>Choose the existing specialty, year or batch, then subject to manage its {purpose}.</p></div><label className="field admin-content-search"><span>Search subjects</span><input type="search" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Histology 1" /></label></div>
    <div className="admin-content-filters"><label className="field"><span>College</span><select value={college} onChange={(event) => { setCollege(event.target.value); setSpecialty(""); setYear(""); }}><option value="">All colleges</option>{colleges.map((value) => <option key={value} value={value}>{value}</option>)}</select></label><label className="field"><span>Specialty</span><select value={specialty} onChange={(event) => { setSpecialty(event.target.value); setYear(""); }}><option value="">All specialties</option>{specialties.map((value) => <option key={value} value={value}>{value}</option>)}</select></label><label className="field"><span>Year / batch</span><select value={year} onChange={(event) => setYear(event.target.value)}><option value="">All years / batches</option>{years.map((value) => <option key={value} value={value}>{value}</option>)}</select></label></div>
    <div className="admin-subject-list">{visibleSubjects.length ? visibleSubjects.map((subject) => <button type="button" key={subject.id} onClick={() => onSelect(subject)}><span className="stat-icon"><Icon name="book-open" /></span><span><strong>{subject.title}</strong><small>{subject.college_title || "Unassigned"} · {subject.specialty_title || "Unassigned"} · {subject.academic_year_title || "Unassigned"} · {subject.sheet_count} sheets · {subject.published_count} published</small></span><Icon name="chevron-right" size={18} /></button>) : <EmptyState title="No Catalog subjects found" text="The selected Catalog study path has no configured subjects." />}</div>
  </section>;
}

function SheetsArea({ canManage }) {
  const [subject, setSubject] = useState(null);
  if (!subject) return <SubjectBrowser selected={subject} onSelect={setSubject} />;
  return <SheetList subject={subject} canManage={canManage} onBack={() => setSubject(null)} />;
}

function SheetList({ subject, canManage, onBack, selectMode = false, onSelectSheet = null }) {
  const [status, setStatus] = useState(""); const [query, setQuery] = useState(""); const [createOpen, setCreateOpen] = useState(false); const [message, setMessage] = useState("");
  const data = useAsyncData(() => adminControlApi.subjectSheets(subject.id, { status, query }), [subject.id, status, query]);
  return <section className="admin-content-section">
    <BreadcrumbButton onClick={onBack}>All subjects</BreadcrumbButton>
    <div className="admin-content-toolbar"><div><h2>{subject.title}</h2><p>{selectMode ? "Choose a sheet to manage its questions." : "Published order is shared with the student Materials view."}</p></div>{canManage && !selectMode && <button className="btn btn-primary" type="button" onClick={() => setCreateOpen((value) => !value)}><Icon name="plus" size={17} />{createOpen ? "Close" : "Add sheet"}</button>}</div>
    {message && <AdminNotice message={message} />}
    {createOpen && <AddSheetForm subject={subject} onCreated={() => { setCreateOpen(false); setMessage("Sheet saved successfully."); data.reload(); }} />}
    <div className="admin-content-filters"><label className="field"><span>Search sheets</span><input type="search" value={query} onChange={(event) => setQuery(event.target.value)} /></label><label className="field"><span>Status</span><select value={status} onChange={(event) => setStatus(event.target.value)}><option value="">All</option>{["draft", "in_review", "published", "rejected", "archived"].map((value) => <option key={value} value={value}>{humanize(value)}</option>)}</select></label></div>
    {data.loading ? <LoadingPanel /> : data.error ? <ErrorPanel message={data.error} onRetry={data.reload} /> : <div className="admin-sheet-list">{data.data.results.length ? data.data.results.map((sheet, index) => selectMode ? <button className="admin-sheet-select" type="button" key={sheet.id} onClick={() => onSelectSheet?.(sheet)}><span><strong>{sheet.title}</strong><small>{sheet.question_count} questions · {humanize(sheet.workflow_status)}</small></span><Icon name="chevron-right" size={18} /></button> : <SheetRow key={sheet.id} sheet={sheet} sheets={data.data.results} index={index} canManage={canManage} onChanged={data.reload} />) : <EmptyState title="No sheets in this view" text="Change the filters or add the first PDF sheet." />}</div>}
  </section>;
}

function AddSheetForm({ subject, onCreated }) {
  const [title, setTitle] = useState(""); const [position, setPosition] = useState(0); const [status, setStatus] = useState("published"); const [notify, setNotify] = useState(true); const [allowDownload, setAllowDownload] = useState(false); const [file, setFile] = useState(null); const [pending, setPending] = useState(false); const [phase, setPhase] = useState(""); const [error, setError] = useState(null);
  async function submit(event) { event.preventDefault(); if (!file || pending) return; setPending(true); setError(null); try { setPhase("Uploading and validating PDF…"); const managed = await managementApi.uploadFile({ kind: "pdf", file }); setPhase("Saving sheet…"); await adminControlApi.createSheet(subject.id, { title, primary_file_id: managed.id, position: Number(position), publish: status === "published", notify_students: status === "published" && notify, allow_download: allowDownload }); onCreated(); } catch (requestError) { setError(requestError); } finally { setPending(false); setPhase(""); } }
  function choose(event) { const next = event.target.files?.[0] || null; if (next && (next.type !== "application/pdf" || !next.name.toLowerCase().endsWith(".pdf"))) { setError(new Error("Choose a valid PDF file.")); setFile(null); return; } if (next && next.size > 50 * 1024 * 1024) { setError(new Error("The PDF exceeds the 50 MB upload limit.")); setFile(null); return; } setFile(next); setError(null); }
  return <form className="admin-sheet-form" onSubmit={submit}><div className="admin-form-heading"><div><h3>Add sheet to {subject.title}</h3><p>The subject is fixed by this page and is never read from the file name. A draft is visible here and to no student.</p></div><span className="pill">Students see published sheets only</span></div><div className="admin-form-grid"><label className="field"><span>Sheet name</span><input value={title} maxLength={220} required onChange={(event) => setTitle(event.target.value)} placeholder="Cell" /></label><label className="field"><span>Order / position</span><input type="number" min="0" max="1000000" value={position} onChange={(event) => setPosition(Number(event.target.value))} /></label><label className="field"><span>Status</span><select value={status} onChange={(event) => setStatus(event.target.value)}><option value="draft">Draft</option><option value="published">Published</option></select></label></div><label className="admin-file-drop"><span className="stat-icon"><Icon name="file" /></span><span><strong>{file ? file.name : "Choose PDF"}</strong><small>{file ? `${bytes(file.size)} · application/pdf` : "PDF only · maximum 50 MB · server signature validation"}</small></span><input type="file" accept="application/pdf,.pdf" required onChange={choose} /></label><div className="admin-form-checks"><label className="check-row"><input type="checkbox" checked={allowDownload} onChange={(event) => setAllowDownload(event.target.checked)} /> Allow student download</label><label className="check-row"><input type="checkbox" checked={notify} disabled={status !== "published"} onChange={(event) => setNotify(event.target.checked)} /> Notify students after publishing</label></div>{pending && <div className="admin-upload-status" role="status"><progress />{phase}</div>}<AdminNotice error={error} /><button className="btn btn-primary" type="submit" disabled={!file || pending}>{pending ? "Working…" : status === "published" ? "Upload & publish" : "Save as draft"}</button></form>;
}

function SheetRow({ sheet, sheets, index, canManage, onChanged }) {
  const [pending, setPending] = useState(""); const [error, setError] = useState(null); const [confirm, setConfirm] = useState(null); const [replacement, setReplacement] = useState(null); const [position, setPosition] = useState(sheet.position); const [title, setTitle] = useState(sheet.title); const [advanced, setAdvanced] = useState(false);
  async function run(action, target = null, placement = null) { setPending(action); setError(null); try { if (action === "replace") { const managed = await managementApi.uploadFile({ kind: "pdf", file: replacement }); await adminControlApi.replaceSheetPdf(sheet.id, { expected_revision: sheet.revision, primary_file_id: managed.id, notify_students: false }); setReplacement(null); } else if (action === "reorder") await adminControlApi.reorderSheet(sheet.id, { expected_revision: sheet.revision, target_sheet_id: target.id, placement }); else if (action === "remove-pdf") await adminControlApi.removeSheetPdf(sheet.id, sheet.revision); else if (action === "delete") await adminControlApi.deleteSheet(sheet.id); else if (action === "details") await adminControlApi.updateSheet(sheet.id, { expected_revision: sheet.revision, title: title.trim(), position: Number(position) }); else await adminControlApi.sheetAction(sheet.id, { expected_revision: sheet.revision, action, notify_students: false }); setConfirm(null); onChanged(); } catch (requestError) { setError(requestError); } finally { setPending(""); } }
  return <article className="admin-sheet-row"><div className="admin-sheet-primary"><span className="admin-order">{sheet.position}</span><div><h3>{sheet.title}</h3><p>{sheet.pdf ? `${sheet.pdf.original_name} · ${bytes(sheet.pdf.size_bytes)}` : "No PDF attached"}</p><small>{sheet.question_count} questions · Active Study {sheet.active_study_enabled ? "enabled" : "disabled"} · Updated {formatDateTime(sheet.updated_at)}</small></div><span className={`pill status-${sheet.workflow_status}`}>{humanize(sheet.workflow_status)}</span>{sheet.workflow_status === "published" && sheet.student_visible === false && <span className="pill status-rejected" title="This subject is not inside any cohort's content root, so the Catalog cannot reach the sheet.">Not visible to students</span>}</div>{error && <AdminNotice error={error} />}{canManage && <details><summary>Manage sheet <Icon name="chevron-right" size={17} /></summary><div className="admin-sheet-actions"><label className="field"><span>Sheet name</span><input value={title} maxLength={220} required onChange={(event) => setTitle(event.target.value)} /></label><label className="field compact-field"><span>Position</span><input type="number" min="0" value={position} onChange={(event) => setPosition(event.target.value)} /></label><button className="btn btn-soft compact" type="button" disabled={Boolean(pending) || !title.trim()} onClick={() => run("details")}>Save details</button><button className="btn btn-soft compact" type="button" disabled={Boolean(pending) || index === 0} onClick={() => run("reorder", sheets[index - 1], "before")}>Move before</button><button className="btn btn-soft compact" type="button" disabled={Boolean(pending) || index === sheets.length - 1} onClick={() => run("reorder", sheets[index + 1], "after")}>Move after</button><button className="btn btn-soft compact" type="button" onClick={() => setAdvanced((value) => !value)}>Advanced</button>{sheet.workflow_status === "published" ? <button className="btn btn-soft compact" type="button" disabled={Boolean(pending)} onClick={() => setConfirm("unpublish")}>Unpublish</button> : sheet.pdf && sheet.workflow_status !== "archived" ? <button className="btn btn-primary compact" type="button" disabled={Boolean(pending)} onClick={() => run("publish")}>Publish</button> : null}<label className="btn btn-soft compact admin-file-button">{replacement ? replacement.name : "Replace PDF"}<input type="file" accept="application/pdf,.pdf" onChange={(event) => setReplacement(event.target.files?.[0] || null)} /></label>{replacement && <button className="btn btn-primary compact" type="button" disabled={Boolean(pending)} onClick={() => run("replace")}>{pending === "replace" ? "Uploading…" : "Confirm replacement"}</button>}{sheet.pdf && <button className="btn btn-soft compact" type="button" disabled={Boolean(pending)} onClick={() => setConfirm("remove-pdf")}>Remove PDF</button>}{sheet.workflow_status !== "archived" && <button className="btn btn-outline compact" type="button" disabled={Boolean(pending)} onClick={() => setConfirm("archive")}>Archive sheet</button>}{sheet.can_permanently_delete && <button className="btn btn-danger compact" type="button" disabled={Boolean(pending)} onClick={() => setConfirm("delete")}>Delete permanently</button>}</div>{advanced && <ActiveStudySettings sheet={sheet} onSaved={onChanged} />}</details>}<ConfirmDialog open={Boolean(confirm)} title={confirm === "delete" ? `Delete “${sheet.title}”?` : confirm === "remove-pdf" ? `Remove the PDF from “${sheet.title}”?` : `${humanize(confirm)} “${sheet.title}”?`} message={confirm === "delete" ? "The server verified that this unpublished sheet has no progress, bookmarks, questions, imports, or publication history. This removes its remaining file." : confirm === "remove-pdf" ? "Students will immediately lose access to the published PDF. Historical file data is retained safely, and the sheet becomes a draft." : confirm === "archive" ? "The sheet disappears from student discovery while historical progress remains intact." : "The sheet remains stored and can be published again later."} confirmLabel={pending ? "Working…" : humanize(confirm)} onCancel={() => setConfirm(null)} onConfirm={() => run(confirm)} /></article>;
}

function ExclusionField({ label, value, onChange }) {
  const numeric = Number(value || 0); const preset = [0, 1, 2, 3].includes(numeric) ? String(numeric) : "custom";
  return <label className="field"><span>{label}</span><select value={preset} onChange={(event) => onChange(event.target.value === "custom" ? (numeric > 3 ? numeric : "") : Number(event.target.value))}><option value="0">None</option><option value="1">1 page</option><option value="2">2 pages</option><option value="3">3 pages</option><option value="custom">Custom</option></select>{preset === "custom" && <input type="number" min="0" max="9999" value={value} required aria-label={`${label}, custom page count`} onChange={(event) => onChange(event.target.value)} placeholder="Pages" />}</label>;
}

function ActiveStudySettings({ sheet, onSaved }) {
  const data = useAsyncData(() => adminControlApi.activeStudySettings(sheet.id), [sheet.id]);
  const [form, setForm] = useState(null); const [pending, setPending] = useState(false); const [error, setError] = useState(null); const [confirm, setConfirm] = useState(false);
  useEffect(() => { if (data.data) setForm({ enabled: Boolean(data.data.enabled), total_pdf_pages: data.data.total_pdf_pages || "", excluded_start_pages: data.data.excluded_start_pages || 0, excluded_end_pages: data.data.excluded_end_pages || 0 }); }, [data.data]);
  if (data.loading || !form) return <LoadingPanel />;
  if (data.error) return <ErrorPanel message={data.error} onRetry={data.reload} />;
  const plan = data.data;
  const boundariesChanged = Number(form.total_pdf_pages || 0) !== Number(plan.total_pdf_pages || 0) || Number(form.excluded_start_pages || 0) !== Number(plan.excluded_start_pages || 0) || Number(form.excluded_end_pages || 0) !== Number(plan.excluded_end_pages || 0);
  function change(key, value) { setForm((current) => ({ ...current, [key]: value })); }
  async function save(confirmed = false) {
    if (plan.existing_question_content && boundariesChanged && !confirmed) { setConfirm(true); return; }
    setPending(true); setError(null);
    try {
      await adminControlApi.updateActiveStudySettings(sheet.id, { expected_revision: plan.revision, enabled: form.enabled, total_pdf_pages: form.total_pdf_pages === "" ? null : Number(form.total_pdf_pages), excluded_start_pages: Number(form.excluded_start_pages || 0), excluded_end_pages: Number(form.excluded_end_pages || 0), confirm_boundary_change: confirmed });
      setConfirm(false); await data.reload(); onSaved();
    } catch (requestError) { setError(requestError); } finally { setPending(false); }
  }
  return <section className="admin-active-study" aria-label={`Active Study settings for ${sheet.title}`}><div className="admin-form-heading"><div><h3>Active Study settings</h3><p>Saved page boundaries and question content are validated by the backend.</p></div><span className={`pill ${form.enabled ? "status-published" : "status-draft"}`}>{form.enabled ? "Enabled" : "Disabled"}</span></div><label className="check-row"><input type="checkbox" checked={form.enabled} onChange={(event) => change("enabled", event.target.checked)} /> Enable Active Study for this sheet</label><div className="admin-form-grid"><label className="field"><span>Total PDF pages</span><input type="number" min="1" max="10000" required={form.enabled} value={form.total_pdf_pages} onChange={(event) => change("total_pdf_pages", event.target.value)} placeholder="22" /></label><ExclusionField label="Exclude from beginning" value={form.excluded_start_pages} onChange={(value) => change("excluded_start_pages", value)} /><ExclusionField label="Exclude from end" value={form.excluded_end_pages} onChange={(value) => change("excluded_end_pages", value)} /></div>{plan.total_pdf_pages != null && <div className="admin-active-study-summary"><strong>Total pages: {plan.total_pdf_pages}</strong><span>Excluded: {plan.excluded_start_pages + plan.excluded_end_pages}</span><span>Study pages: {plan.eligible_study_pages}</span></div>}<div className="admin-active-study-plans">{plan.difficulties.map((difficulty) => <ActiveStudyDifficultyContent key={difficulty.difficulty} sheet={sheet} difficulty={difficulty} activeStudyEnabled={plan.enabled} onContentChanged={data.reload} />)}</div>{plan.existing_question_content && boundariesChanged && <p className="form-alert">Changing excluded pages changes Active Study part boundaries. Existing question configuration may no longer match this sheet.</p>}<AdminNotice error={error} /><button className="btn btn-primary compact" type="button" disabled={pending} onClick={() => save()}>{pending ? "Saving…" : "Save Active Study settings"}</button><ConfirmDialog open={confirm} title="Update Active Study boundaries?" message="Changing these boundaries may make existing question configuration incompatible. Existing JSON is retained and will be marked Needs Review when its structure no longer matches." confirmLabel={pending ? "Saving…" : "Save changes"} onCancel={() => setConfirm(false)} onConfirm={() => save(true)} /></section>;
}

function ActiveStudyDifficultyContent({ sheet, difficulty, activeStudyEnabled, onContentChanged }) {
  const data = useAsyncData(() => adminControlApi.activeStudyQuestions(sheet.id, difficulty.difficulty), [sheet.id, difficulty.difficulty]);
  const [editor, setEditor] = useState(false); const [preview, setPreview] = useState(false); const [confirmDelete, setConfirmDelete] = useState(false); const [pending, setPending] = useState(false); const [error, setError] = useState(null);
  const fallback = difficulty.content || { status: "not_configured", checkpoint_question_count: 0, checkpoint_question_target: difficulty.number_of_parts * difficulty.questions_per_checkpoint, final_exam_question_count: 0, final_exam_question_target: difficulty.final_exam_questions, revision: 0 };
  const content = data.data?.content || fallback;
  const readinessReason = content.readiness?.reason || difficulty.readiness?.reason || "Questions have not been configured.";
  async function remove() { setPending(true); setError(null); try { await adminControlApi.deleteActiveStudyQuestions(sheet.id, difficulty.difficulty, content.revision); setConfirmDelete(false); setPreview(false); await data.reload(); await onContentChanged(); } catch (requestError) { setError(requestError); } finally { setPending(false); } }
  return <article className="admin-active-study-difficulty"><header><div><h4>{humanize(difficulty.difficulty)}</h4><p>{difficulty.number_of_parts} parts · {difficulty.target_pages_per_part} target pages per part</p></div><span className={`creator-badge active-study-status-${content.status}`}>{humanize(content.status)}</span></header>{content.status !== "ready" && <p className="form-alert">Unavailable — {readinessReason}</p>}<p className="admin-active-study-rules">Checkpoint questions: {content.checkpoint_question_count} / {content.checkpoint_question_target} · Final exam: {content.final_exam_question_count} / {content.final_exam_question_target}</p><ol>{difficulty.page_ranges.map((range) => <li key={range.part}>Part {range.part}: Pages {range.start_page}–{range.end_page}</li>)}</ol>{data.loading && <small>Loading question content…</small>}{data.error && <AdminNotice error={data.error} />}{error && <AdminNotice error={error} />}{content.status === "needs_review" && <p className="form-alert">Page boundaries changed after this import. Review and replace this JSON before using it.</p>}{!difficulty.prompt_template_supported && <p className="form-alert error">This sheet produces {difficulty.number_of_parts} Active Study parts. A matching prompt template is not configured yet.</p>}<div className="admin-active-study-content-actions"><ActiveStudyCopyPromptButton difficulty={difficulty} enabled={activeStudyEnabled} /><button className="btn btn-primary compact" type="button" disabled={data.loading} onClick={() => { setEditor(true); setPreview(false); }}>{content.revision ? "Edit / Replace JSON" : "Import JSON"}</button>{content.revision > 0 && <><button className="btn btn-soft compact" type="button" onClick={() => { setPreview((value) => !value); setEditor(false); }}>{preview ? "Close preview" : "Preview"}</button><button className="btn btn-danger compact" type="button" disabled={pending} onClick={() => setConfirmDelete(true)}>Delete content</button></>}</div>{editor && <ActiveStudyJsonEditor sheet={sheet} difficulty={difficulty} existingPayload={data.data?.content?.payload || null} expectedRevision={content.revision} onCancel={() => setEditor(false)} onSaved={async () => { setEditor(false); await data.reload(); await onContentChanged(); }} />}{preview && data.data?.content?.payload && <ActiveStudyQuestionPreview payload={data.data.content.payload} pageRanges={difficulty.page_ranges} />}<ConfirmDialog open={confirmDelete} title={`Delete ${humanize(difficulty.difficulty)} Active Study questions?`} message="Only this difficulty's JSON questions will be deleted. Active Study settings, other difficulties, the sheet, and its PDF remain unchanged." confirmLabel={pending ? "Deleting…" : "Delete content"} onCancel={() => setConfirmDelete(false)} onConfirm={remove} /></article>;
}

function ActiveStudyCopyPromptButton({ difficulty, enabled }) {
  const [status, setStatus] = useState(""); const [fallbackPrompt, setFallbackPrompt] = useState("");
  const plan = { difficulty: difficulty.difficulty, numberOfParts: difficulty.number_of_parts, pageRanges: difficulty.page_ranges, questionsPerPart: difficulty.questions_per_checkpoint, finalExamQuestions: difficulty.final_exam_questions };
  let prompt = ""; let planError = null;
  try { prompt = buildActiveStudyJsonPrompt(plan); } catch (error) { planError = error instanceof Error ? error.message : "Active Study plan is invalid."; }
  async function copy() { if (!prompt) return; setStatus(""); setFallbackPrompt(""); try { await navigator.clipboard.writeText(prompt); setStatus("Prompt copied"); } catch { setFallbackPrompt(prompt); setStatus("Clipboard access failed. Copy the prompt manually below."); } }
  return <><button className="btn btn-soft compact" type="button" disabled={!enabled || Boolean(planError)} onClick={copy}>Copy JSON Prompt</button>{!enabled && <small className="admin-active-study-copy-status">Enable Active Study to copy its prompt.</small>}{planError && <small className="form-alert error">{planError}</small>}{status && <small className="admin-active-study-copy-status" role="status">{status}</small>}{fallbackPrompt && <label className="field admin-active-study-copy-fallback"><span>Copy JSON Prompt manually</span><textarea readOnly value={fallbackPrompt} onFocus={(event) => event.target.select()} /></label>}</>;
}

function ActiveStudyValidationErrors({ error }) {
  const errors = Array.isArray(error?.payload?.errors) ? error.payload.errors : [];
  if (!errors.length) return <AdminNotice error={error} />;
  return <div className="form-alert error" role="alert"><strong>JSON needs correction.</strong><ul>{errors.slice(0, 12).map((item, index) => <li key={`${item.path}-${index}`}><b>{item.path || "JSON"}</b>: {item.message}</li>)}</ul></div>;
}

function ActiveStudyJsonEditor({ sheet, difficulty, existingPayload, expectedRevision, onCancel, onSaved }) {
  const [text, setText] = useState(() => JSON.stringify(existingPayload || { parts: [], final_exam: { questions: [] } }, null, 2)); const [validation, setValidation] = useState(null); const [validatedText, setValidatedText] = useState(""); const [pending, setPending] = useState(""); const [error, setError] = useState(null);
  async function validate() { setPending("validate"); setError(null); setValidation(null); try { const payload = JSON.parse(text); const result = await adminControlApi.validateActiveStudyQuestions(sheet.id, difficulty.difficulty, payload); setValidation(result); setValidatedText(text); } catch (requestError) { setValidatedText(""); setError(requestError instanceof SyntaxError ? new Error(`Invalid JSON syntax: ${requestError.message}`) : requestError); } finally { setPending(""); } }
  async function save() { if (!validation || text !== validatedText) { setError(new Error("Validate the current JSON before saving.")); return; } setPending("save"); setError(null); try { await adminControlApi.saveActiveStudyQuestions(sheet.id, difficulty.difficulty, { expected_revision: expectedRevision, payload: JSON.parse(text) }); await onSaved(); } catch (requestError) { setError(requestError); } finally { setPending(""); } }
  return <section className="admin-active-study-editor"><div><h5>{expectedRevision ? `Replace ${humanize(difficulty.difficulty)} JSON` : `Import ${humanize(difficulty.difficulty)} JSON`}</h5><p>Paste exactly {difficulty.number_of_parts} parts with {difficulty.questions_per_checkpoint} MCQs each, plus {difficulty.final_exam_questions} final-exam MCQs.</p></div><label className="field admin-json-field"><span>Paste JSON</span><textarea spellCheck="false" value={text} onChange={(event) => { setText(event.target.value); setValidation(null); setValidatedText(""); }} /></label><div className="admin-active-study-content-actions"><button className="btn btn-soft compact" type="button" onClick={onCancel} disabled={Boolean(pending)}>Cancel</button><button className="btn btn-primary compact" type="button" disabled={!text.trim() || Boolean(pending)} onClick={validate}>{pending === "validate" ? "Validating…" : "Validate"}</button><button className="btn btn-primary compact" type="button" disabled={!validation || text !== validatedText || Boolean(pending)} onClick={save}>{pending === "save" ? "Saving…" : "Save"}</button></div>{validation && <><div className="admin-validation"><strong>Valid JSON</strong><span>{difficulty.number_of_parts} Parts · {validation.checkpoint_question_count} Checkpoint Questions · {validation.final_exam_question_count} Final Exam Questions</span></div><ActiveStudyQuestionPreview payload={validation.payload} pageRanges={difficulty.page_ranges} /></>}<ActiveStudyValidationErrors error={error} /></section>;
}

function ActiveStudyQuestionPreview({ payload, pageRanges }) {
  const [section, setSection] = useState("part-1"); const parts = Array.isArray(payload?.parts) ? payload.parts : []; const finalQuestions = Array.isArray(payload?.final_exam?.questions) ? payload.final_exam.questions : []; const currentPart = parts.find((part) => `part-${part.part}` === section); const questions = currentPart ? currentPart.questions : finalQuestions; const range = currentPart ? pageRanges.find((item) => item.part === currentPart.part) : null;
  return <section className="admin-active-study-preview"><div className="admin-active-study-content-actions">{parts.map((part) => <button key={part.part} className={`btn btn-soft compact ${section === `part-${part.part}` ? "is-active" : ""}`} type="button" onClick={() => setSection(`part-${part.part}`)}>Part {part.part}</button>)}<button className={`btn btn-soft compact ${section === "final" ? "is-active" : ""}`} type="button" onClick={() => setSection("final")}>Final exam</button></div><p>{currentPart ? `Part ${currentPart.part} · Pages ${range?.start_page}–${range?.end_page} · ${questions.length} questions` : `Final exam · ${questions.length} questions`}</p><div className="admin-active-study-preview-list">{questions.map((question, index) => <details key={index}><summary>Q{index + 1}. {question.question}</summary><div><ol type="A">{["A", "B", "C", "D"].map((key) => <li key={key} className={question.correct_answer === key ? "is-correct" : ""}>{question.options?.[key]}</li>)}</ol><p><strong>Correct answer:</strong> {question.correct_answer}</p><p><strong>Explanation:</strong> {question.explanation}</p></div></details>)}</div></section>;
}

function QuestionsArea({ canManage }) {
  const [subject, setSubject] = useState(null); const [sheet, setSheet] = useState(null);
  if (!subject) return <SubjectBrowser selected={subject} onSelect={setSubject} purpose="question sheets" />;
  if (!sheet) return <SheetList subject={subject} canManage={false} selectMode onSelectSheet={setSheet} onBack={() => setSubject(null)} />;
  return <QuestionList subject={subject} sheet={sheet} canManage={canManage} onBack={() => setSheet(null)} />;
}

function QuestionList({ subject, sheet, canManage, onBack }) {
  const [filters, setFilters] = useState({ query: "", status: "", type: "", difficulty: "", topic: "" }); const [selected, setSelected] = useState([]); const [importOpen, setImportOpen] = useState(false); const [editing, setEditing] = useState(null); const [error, setError] = useState(null); const [pending, setPending] = useState(""); const [confirm, setConfirm] = useState(null); const [targetSheetId, setTargetSheetId] = useState("");
  const data = useAsyncData(() => adminControlApi.sheetQuestions(sheet.id, filters), [sheet.id, filters.query, filters.status, filters.type, filters.difficulty, filters.topic]);
  const sheetOptions = useAsyncData(() => adminControlApi.subjectSheets(subject.id), [subject.id]);
  function change(key, value) { setFilters((current) => ({ ...current, [key]: value })); setSelected([]); }
  async function bulk(action) { if (!selected.length || (action === "move" && !targetSheetId)) return; setPending(action); setError(null); try { await adminControlApi.bulkQuestions(selected, action, action === "move" ? targetSheetId : null); setSelected([]); setConfirm(null); data.reload(); } catch (requestError) { setError(requestError); } finally { setPending(""); } }
  const results = data.data?.results || []; const allSelected = results.length > 0 && results.every((item) => selected.includes(item.id));
  return <section className="admin-content-section"><BreadcrumbButton onClick={onBack}>{subject.title}</BreadcrumbButton><div className="admin-content-toolbar"><div><h2>{sheet.title}</h2><p>{data.data ? `${data.data.count} questions · ${Object.entries(data.data.type_counts).map(([key, value]) => `${value} ${humanize(key)}`).join(" · ") || "No types"}` : "Loading question summary…"}</p></div>{canManage && <button className="btn btn-primary" type="button" onClick={() => setImportOpen((value) => !value)}><Icon name="plus" size={17} />{importOpen ? "Close importer" : "Add questions"}</button>}</div>{importOpen && <QuestionImporter sheet={sheet} onImported={() => { setImportOpen(false); data.reload(); }} />}<div className="admin-question-filters"><label className="field"><span>Search</span><input type="search" value={filters.query} onChange={(event) => change("query", event.target.value)} /></label><label className="field"><span>Topic</span><input value={filters.topic} onChange={(event) => change("topic", event.target.value)} /></label><label className="field"><span>Type</span><select value={filters.type} onChange={(event) => change("type", event.target.value)}><option value="">All</option>{["single_choice", "true_false", "multiple_select"].map((value) => <option key={value} value={value}>{humanize(value)}</option>)}</select></label><label className="field"><span>Status</span><select value={filters.status} onChange={(event) => change("status", event.target.value)}><option value="">All</option>{["draft", "in_review", "published", "rejected", "retired"].map((value) => <option key={value} value={value}>{humanize(value)}</option>)}</select></label><label className="field"><span>Difficulty</span><select value={filters.difficulty} onChange={(event) => change("difficulty", event.target.value)}><option value="">All</option>{["easy", "medium", "hard"].map((value) => <option key={value}>{humanize(value)}</option>)}</select></label></div>{error && <AdminNotice error={error} />}{canManage && results.length > 0 && <div className="admin-bulk-bar"><label className="check-row"><input type="checkbox" checked={allSelected} onChange={() => setSelected(allSelected ? selected.filter((id) => !results.some((item) => item.id === id)) : [...new Set([...selected, ...results.map((item) => item.id)])])} /> Select all</label><span>{selected.length} selected</span><button className="btn btn-soft compact" disabled={!selected.length || Boolean(pending)} type="button" onClick={() => bulk("publish")}>Publish</button><button className="btn btn-soft compact" disabled={!selected.length || Boolean(pending)} type="button" onClick={() => bulk("unpublish")}>Unpublish</button><label className="field compact-field"><span>Move to</span><select value={targetSheetId} onChange={(event) => setTargetSheetId(event.target.value)}><option value="">Choose sheet</option>{(sheetOptions.data?.results || []).filter((item) => item.id !== sheet.id).map((item) => <option key={item.id} value={item.id}>{item.title}</option>)}</select></label><button className="btn btn-soft compact" disabled={!selected.length || !targetSheetId || Boolean(pending)} type="button" onClick={() => bulk("move")}>Move</button><button className="btn btn-danger compact" disabled={!selected.length || Boolean(pending)} type="button" onClick={() => setConfirm("delete")}>Archive selected</button></div>}{data.loading ? <LoadingPanel /> : data.error ? <ErrorPanel message={data.error} onRetry={data.reload} /> : <div className="admin-question-list">{results.length ? results.map((question, index) => <article key={question.id}><label className="admin-question-select"><input type="checkbox" checked={selected.includes(question.id)} onChange={() => setSelected((current) => current.includes(question.id) ? current.filter((id) => id !== question.id) : [...current, question.id])} /><span>Q{index + 1}</span></label><div className="admin-question-copy"><h3>{question.question}</h3><p>{humanize(question.question_type)} · {humanize(question.difficulty)}{question.topic ? ` · ${question.topic}` : ""}</p><small>{question.explanation || "No explanation"}</small></div><div className="admin-question-meta"><span className={`pill status-${question.workflow_status}`}>{humanize(question.workflow_status)}</span>{canManage && <button className="btn btn-soft compact" type="button" onClick={() => setEditing(editing === question.id ? null : question.id)}><Icon name="pencil" size={15} />Edit</button>}{canManage && <button className="btn btn-danger compact" type="button" onClick={() => { setSelected([question.id]); setConfirm("delete"); }}><Icon name="trash" size={15} />Archive</button>}</div>{editing === question.id && <QuestionEditor question={question} sheet={data.data.sheet} onSaved={() => { setEditing(null); data.reload(); }} />}</article>) : <EmptyState title="No questions found" text="Import a JSON batch or change the filters." />}</div>}<ConfirmDialog open={confirm === "delete"} title={`Archive ${selected.length} questions?`} message="The questions will be retired from future quizzes. Student attempts, Review Bank entries, analytics, and immutable question versions remain intact." confirmLabel={pending ? "Working…" : "Archive questions"} onCancel={() => setConfirm(null)} onConfirm={() => bulk("delete")} /></section>;
}

function QuestionEditor({ question, sheet, onSaved }) {
  const [form, setForm] = useState(() => ({ prompt: question.question, explanation: question.explanation, difficulty: question.difficulty, topic: question.topic, sourcePage: question.source_page || "", options: question.choices.map((choice) => ({ text: choice.text, isCorrect: choice.is_correct })) })); const [pending, setPending] = useState(false); const [error, setError] = useState(null);
  function change(key, value) { setForm((current) => ({ ...current, [key]: value })); }
  async function save(event) { event.preventDefault(); setPending(true); setError(null); try { await managementApi.updateQuestion(question.id, { academicNodeId: sheet.subject_id, sourceLearningObjectId: sheet.id, questionType: question.question_type, prompt: form.prompt, explanation: form.explanation, difficulty: form.difficulty, language: "en", topic: form.topic, sourcePage: form.sourcePage, options: form.options, expectedRevision: question.revision }); onSaved(); } catch (requestError) { setError(requestError); } finally { setPending(false); } }
  return <form className="admin-question-editor" onSubmit={save}><label className="field"><span>Question</span><textarea value={form.prompt} required onChange={(event) => change("prompt", event.target.value)} /></label><div className="admin-form-grid"><label className="field"><span>Difficulty</span><select value={form.difficulty} onChange={(event) => change("difficulty", event.target.value)}>{["easy", "medium", "hard"].map((value) => <option key={value}>{value}</option>)}</select></label><label className="field"><span>Topic</span><input value={form.topic} maxLength={220} onChange={(event) => change("topic", event.target.value)} /></label><label className="field"><span>Source page (stored only)</span><input type="number" min="1" value={form.sourcePage} onChange={(event) => change("sourcePage", event.target.value)} /></label></div><div className="admin-option-editor">{form.options.map((option, index) => <label key={index}><span className="sr-only">Option {index + 1}; mark it correct, then edit its text</span><input type={question.question_type === "multiple_select" ? "checkbox" : "radio"} name={`correct-${question.id}`} checked={option.isCorrect} onChange={() => change("options", form.options.map((item, itemIndex) => ({ ...item, isCorrect: question.question_type === "multiple_select" ? itemIndex === index ? !item.isCorrect : item.isCorrect : itemIndex === index })))} /><input value={option.text} required onChange={(event) => change("options", form.options.map((item, itemIndex) => itemIndex === index ? { ...item, text: event.target.value } : item))} /></label>)}</div><label className="field"><span>Explanation</span><textarea value={form.explanation} onChange={(event) => change("explanation", event.target.value)} /></label><AdminNotice error={error} /><button className="btn btn-primary compact" type="submit" disabled={pending}>{pending ? "Saving…" : "Save new revision"}</button></form>;
}

function blankQuestion(type, index) {
  const common = { type, question: `Question ${index + 1}`, explanation: "", difficulty: "medium", topic: "", source_page: null };
  if (type === "true_false") return { ...common, correct_answer: true };
  const choices = ["Option A", "Option B", "Option C", "Option D"];
  if (type === "multiple_select") return { ...common, choices, correct_answers: [choices[0], choices[1]] };
  return { ...common, choices, correct_answer: choices[0] };
}

function templatePayload(counts) {
  const questions = []; let index = 0;
  for (const type of ["mcq", "true_false", "multiple_select"]) for (let amount = 0; amount < Number(counts[type] || 0); amount += 1) questions.push(blankQuestion(type, index++));
  return { version: "lockin_questions_v1", questions };
}

function aiPrompt(counts) {
  const total = Number(counts.mcq) + Number(counts.true_false) + Number(counts.multiple_select);
  const breakdown = [[counts.mcq, "MCQ"], [counts.true_false, "True / False"], [counts.multiple_select, "Multiple Select"]].filter(([count]) => Number(count) > 0).map(([count, label]) => `- ${count} ${label}`).join("\n");
  return `Create exactly ${total} questions from the lecture I provide.\n${breakdown}\nUse only information from the lecture. Do not invent information outside the source. Include a short explanation for every correct answer. Return ONLY valid JSON. Do not rename, add, or remove JSON keys. Use source_page only when the page is clearly known; otherwise use null. Follow this schema exactly:\n\n${JSON.stringify(templatePayload(counts), null, 2)}`;
}

function QuestionImporter({ sheet, onImported }) {
  const [preset, setPreset] = useState("standard"); const [counts, setCounts] = useState(QUESTION_PRESETS.standard); const [text, setText] = useState(() => JSON.stringify(templatePayload(QUESTION_PRESETS.standard), null, 2)); const [payload, setPayload] = useState(null); const [validation, setValidation] = useState(null); const [validatedToken, setValidatedToken] = useState(""); const [pending, setPending] = useState(""); const [error, setError] = useState(null); const [message, setMessage] = useState("");
  const total = Number(counts.mcq) + Number(counts.true_false) + Number(counts.multiple_select);
  function selectPreset(value) { const next = QUESTION_PRESETS[value]; setPreset(value); setCounts({ ...next }); setValidation(null); }
  function generate() { const next = templatePayload(counts); setPayload(next); setText(JSON.stringify(next, null, 2)); setValidation(null); setValidatedToken(""); setMessage(`Generated a ${total}-question JSON template.`); }
  function setDraft(next) { setPayload(next); setText(JSON.stringify(next, null, 2)); setValidation((current) => current ? { ...current, valid: false, dirty: true } : current); setValidatedToken(""); }
  async function copyPrompt() { try { await navigator.clipboard.writeText(aiPrompt(counts)); setMessage("AI prompt copied. Paste it into ChatGPT with the lecture."); } catch { setError(new Error("Copy was blocked by the browser. Select the generated prompt manually.")); } }
  async function validate() { setPending("validate"); setError(null); try { const parsed = JSON.parse(text); const result = await adminControlApi.validateQuestionImport(sheet.id, parsed); setPayload(parsed); setValidation(result); setValidatedToken(JSON.stringify(parsed)); setMessage("Validation passed. Review every question before importing."); } catch (requestError) { setValidation(null); setValidatedToken(""); setError(requestError instanceof SyntaxError ? new Error(`Invalid JSON syntax: ${requestError.message}`) : requestError); } finally { setPending(""); } }
  async function commit(publish) { if (!payload || JSON.stringify(payload) !== validatedToken) { setError(new Error("Validate the latest edited JSON before importing.")); return; } setPending(publish ? "publish" : "draft"); setError(null); try { await adminControlApi.importQuestions(sheet.id, payload, publish); onImported(); } catch (requestError) { setError(requestError); } finally { setPending(""); } }
  async function upload(event) { const file = event.target.files?.[0]; if (!file) return; if (!file.name.toLowerCase().endsWith(".json") || file.size > 2 * 1024 * 1024) { setError(new Error("Choose a JSON file smaller than 2 MB.")); return; } const content = await file.text(); setText(content); setPayload(null); setValidation(null); setValidatedToken(""); setMessage(`${file.name} loaded. Validate it before import.`); }
  return <section className="admin-importer"><div className="admin-importer-heading"><div><h3>Question import</h3><p>The template is generated on this device. The whole batch is validated and committed together.</p></div><span className="pill">lockin_questions_v1</span></div><RadioGroup className="admin-preset-list" label="Question mix preset" value={preset} onChange={selectPreset}>{Object.entries(QUESTION_PRESETS).map(([key, value]) => <RadioOption className={preset === key ? "active" : ""} key={key} value={key}><strong>{value.label}</strong><small>{value.mcq} MCQ · {value.true_false} T/F · {value.multiple_select} Multi</small></RadioOption>)}</RadioGroup><div className="admin-count-grid">{[["mcq", "MCQ"], ["true_false", "True / False"], ["multiple_select", "Multiple Select"]].map(([key, label]) => <label className="field" key={key}><span>{label}</span><input type="number" min="0" max="200" value={counts[key]} onChange={(event) => { setPreset("custom"); setCounts((current) => ({ ...current, [key]: Number(event.target.value) })); }} /></label>)}</div><div className="admin-template-actions"><button className="btn btn-soft" type="button" disabled={total < 1 || total > 200} onClick={generate}>Generate template</button><button className="btn btn-outline" type="button" disabled={total < 1 || total > 200} onClick={copyPrompt}><Icon name="sparkles" size={17} />Copy AI prompt</button><label className="btn btn-soft admin-file-button">Upload JSON<input type="file" accept="application/json,.json" onChange={(event) => void upload(event)} /></label></div>{message && <AdminNotice message={message} />}<label className="field admin-json-field"><span>Paste JSON</span><textarea spellCheck="false" value={text} onChange={(event) => { setText(event.target.value); setPayload(null); setValidation(null); setValidatedToken(""); }} /></label><button className="btn btn-primary" type="button" disabled={!text.trim() || Boolean(pending)} onClick={validate}>{pending === "validate" ? "Validating…" : "Validate JSON"}</button><AdminNotice error={error} />{validation && payload && <section className="admin-validation"><div className="admin-validation-summary"><div><Icon name={validation.valid ? "check" : "activity"} /><span><strong>{validation.valid ? `${validation.question_count} questions detected` : "Preview changed — validate again"}</strong><small>{Object.entries(validation.type_counts).map(([key, value]) => `${value} ${humanize(key)}`).join(" · ")}</small></span></div><span>{validation.warnings.length} warnings</span></div>{validation.warnings.length > 0 && <ul>{validation.warnings.map((warning, index) => <li key={index}>Question {warning.index + 1}: {warning.message}</li>)}</ul>}<div className="admin-import-preview">{payload.questions.map((question, index) => <ImportQuestionEditor key={index} question={question} index={index} onChange={(updated) => setDraft({ ...payload, questions: payload.questions.map((item, itemIndex) => itemIndex === index ? updated : item) })} onRemove={() => setDraft({ ...payload, questions: payload.questions.filter((_, itemIndex) => itemIndex !== index) })} />)}</div><div className="admin-import-actions"><button className="btn btn-soft" type="button" disabled={Boolean(pending) || !validation.valid} onClick={() => commit(false)}>{pending === "draft" ? "Importing…" : "Save as draft"}</button><button className="btn btn-primary" type="button" disabled={Boolean(pending) || !validation.valid} onClick={() => commit(true)}>{pending === "publish" ? "Publishing…" : "Import & publish"}</button></div></section>}</section>;
}

function ImportQuestionEditor({ question, index, onChange, onRemove }) {
  function change(key, value) { onChange({ ...question, [key]: value }); }
  const choices = Array.isArray(question.choices) ? question.choices : [];
  return <details className="admin-preview-question" open={index < 2}><summary><span>Q{index + 1}</span><strong>{question.question || "Untitled question"}</strong><small>{humanize(question.type)}</small></summary><div><label className="field"><span>Question</span><textarea value={question.question || ""} onChange={(event) => change("question", event.target.value)} /></label><div className="admin-form-grid"><label className="field"><span>Difficulty</span><select value={question.difficulty || "medium"} onChange={(event) => change("difficulty", event.target.value)}>{["easy", "medium", "hard"].map((value) => <option key={value}>{value}</option>)}</select></label><label className="field"><span>Topic</span><input value={question.topic || ""} onChange={(event) => change("topic", event.target.value)} /></label><label className="field"><span>Source page</span><input type="number" min="1" value={question.source_page ?? ""} onChange={(event) => change("source_page", event.target.value ? Number(event.target.value) : null)} /></label></div>{question.type !== "true_false" && <div className="admin-option-editor">{choices.map((choice, choiceIndex) => <label key={choiceIndex}><span className="sr-only">Option {choiceIndex + 1}; mark it correct, then edit its text</span><input type={question.type === "multiple_select" ? "checkbox" : "radio"} name={`preview-correct-${index}`} checked={question.type === "multiple_select" ? (question.correct_answers || []).includes(choice) : question.correct_answer === choice} onChange={() => question.type === "multiple_select" ? change("correct_answers", (question.correct_answers || []).includes(choice) ? question.correct_answers.filter((value) => value !== choice) : [...(question.correct_answers || []), choice]) : change("correct_answer", choice)} /><input value={choice} onChange={(event) => change("choices", choices.map((item, itemIndex) => itemIndex === choiceIndex ? event.target.value : item))} /></label>)}</div>}{question.type === "true_false" && <label className="field"><span>Correct answer</span><select value={String(question.correct_answer)} onChange={(event) => change("correct_answer", event.target.value === "true")}><option value="true">True</option><option value="false">False</option></select></label>}<label className="field"><span>Explanation</span><textarea value={question.explanation || ""} onChange={(event) => change("explanation", event.target.value)} /></label><button className="btn btn-danger compact" type="button" onClick={onRemove}><Icon name="trash" size={15} />Remove from batch</button></div></details>;
}

function ImportHistory({ canManage }) {
  const [status, setStatus] = useState(""); const [confirm, setConfirm] = useState(null); const [pending, setPending] = useState(false); const [error, setError] = useState(null); const data = useAsyncData(() => adminControlApi.importHistory(status), [status]);
  async function undo(batch) { setPending(true); setError(null); try { await adminControlApi.undoImport(batch.id); setConfirm(null); data.reload(); } catch (requestError) { setError(requestError); } finally { setPending(false); } }
  return <section className="admin-content-section"><div className="admin-content-toolbar"><div><h2>Import history</h2><p>Every atomic JSON import has a stable batch ID and safe undo path.</p></div><label className="field compact-field"><span>Status</span><select value={status} onChange={(event) => setStatus(event.target.value)}><option value="">All</option>{["draft", "published", "undone"].map((value) => <option key={value}>{value}</option>)}</select></label></div>{error && <AdminNotice error={error} />}{data.loading ? <LoadingPanel /> : data.error ? <ErrorPanel message={data.error} onRetry={data.reload} /> : <div className="admin-import-history">{data.data.results.length ? data.data.results.map((batch) => <article key={batch.id}><div><strong>{batch.sheet.title}</strong><span>{batch.subject.title} · {batch.admin.name || batch.admin.email}</span><small>{formatDateTime(batch.created_at)} · {batch.batch_id}</small></div><div><b>{formatNumber(batch.question_count)}</b><span>{Object.entries(batch.type_counts).map(([key, value]) => `${value} ${humanize(key)}`).join(" · ")}</span></div><span className={`pill status-${batch.status}`}>{humanize(batch.status)}</span>{canManage && batch.status !== "undone" && <button className="btn btn-danger compact" type="button" onClick={() => setConfirm(batch)}>Undo import</button>}</article>) : <EmptyState title="No imports yet" text="Validated JSON batches will appear here." />}</div>}<ConfirmDialog open={Boolean(confirm)} title={`Undo ${confirm?.batch_id || "import"}?`} message="All questions in this batch will be retired. Attempts, results, analytics, Review Bank, hidden bank, and quiz snapshots remain untouched." confirmLabel={pending ? "Working…" : "Undo safely"} onCancel={() => setConfirm(null)} onConfirm={() => undo(confirm)} /></section>;
}
